JacobiState& jacobi_state() {
  static JacobiState instance;
  return instance;
}

struct CertificateState {
  int device = -1;
  int batch = -1;
  int n = -1;
  torch::Tensor gram;
  torch::Tensor aq;
  torch::Tensor flags;
  torch::Tensor columns;
};

CertificateState& certificate_state() {
  static CertificateState instance;
  return instance;
}

CertificateState& refinement_state() {
  static CertificateState instance;
  return instance;
}

void ensure_certificate_state(
    CertificateState& state, const torch::Tensor& input, int batch, int n) {
  if (state.device == input.get_device() &&
      state.batch == batch && state.n == n) {
    return;
  }
  state.device = input.get_device();
  state.batch = batch;
  state.n = n;
  state.gram = torch::empty_like(input);
  state.aq = torch::empty_like(input);
  state.flags = torch::empty(
      {batch + 1}, input.options().dtype(torch::kInt32));
  state.columns = torch::empty(
      {batch, n}, input.options().dtype(torch::kInt32));
}

struct DenseBatchState {
  int device = -1;
  int* host_flag = nullptr;
  int* device_flag = nullptr;
  int* host_positive_flag = nullptr;
  int* device_positive_flag = nullptr;
  int* host_geometric_flag = nullptr;
  int* device_geometric_flag = nullptr;

  ~DenseBatchState() {
    if (host_flag != nullptr) {
      cudaFreeHost(host_flag);
  CUSOLVER_CHECK(cusolverDnXsyevBatched(
      s.handle, s.params, CUSOLVER_EIG_MODE_VECTOR, uplo, n, CUDA_R_32F,
      vectors_col_major.data_ptr<float>(), n, CUDA_R_32F,
      values.data_ptr<float>(), CUDA_R_32F,
      s.device_bytes == 0 ? nullptr : s.device_workspace.data_ptr(),
      s.device_bytes,
      s.host_bytes == 0 ? nullptr : s.host_workspace.data(), s.host_bytes,
      s.info.data_ptr<int>(), batch));

  // cuSOLVER writes column-major eigenvectors into row-major storage.
  return {vectors_col_major.transpose(1, 2), values};
}

std::vector<torch::Tensor> refine_eigh512(
    torch::Tensor input, torch::Tensor vectors, torch::Tensor values,
    torch::Tensor factor_workspace) {
  TORCH_CHECK(input.is_cuda() && vectors.is_cuda() && values.is_cuda() &&
                  factor_workspace.is_cuda(),
              "n512 refinement inputs must be CUDA tensors");
  TORCH_CHECK(input.scalar_type() == torch::kFloat32 &&
                  vectors.scalar_type() == torch::kFloat32 &&
                  values.scalar_type() == torch::kFloat32 &&
                  factor_workspace.scalar_type() == torch::kFloat32,
              "n512 refinement inputs must be FP32");
  TORCH_CHECK(input.dim() == 3 && input.size(1) == 512 &&
                  input.size(2) == 512 && vectors.sizes() == input.sizes() &&
                  factor_workspace.sizes() == input.sizes() &&
                  values.dim() == 2 && values.size(0) == input.size(0) &&
                  values.size(1) == 512,
              "n512 refinement requires matching batch dimensions");
  TORCH_CHECK(input.is_contiguous() && vectors.is_contiguous() &&
                  values.is_contiguous() && factor_workspace.is_contiguous(),
              "n512 refinement inputs must be contiguous");

  const c10::cuda::CUDAGuard device_guard(input.device());
  const int batch = static_cast<int>(input.size(0));
  CertificateState& initial_state = certificate_state();
  ensure_certificate_state(initial_state, input, batch, 512);
  HighFloat32MatmulGuard high_float32;

  at::bmm_out(initial_state.gram, vectors.transpose(1, 2), vectors);
  at::bmm_out(initial_state.aq, input, vectors);
  certify_and_prepare_eigenpairs512<false, false><<<batch, 512>>>(
      initial_state.gram.data_ptr<float>(), initial_state.aq.data_ptr<float>(),
      vectors.data_ptr<float>(), values.data_ptr<float>(), nullptr,
      initial_state.flags.data_ptr<int>(), initial_state.columns.data_ptr<int>(),
      batch);
  auto unsafe_indices = at::nonzero(
      initial_state.flags.narrow(0, 0, batch)).flatten();
  const int candidate_count = static_cast<int>(unsafe_indices.size(0));
  if (candidate_count == 0) {
    auto empty_indices = torch::empty(
        {0}, input.options().dtype(torch::kInt64));
    auto empty_flags = torch::empty(
        {0}, input.options().dtype(torch::kInt32));
    auto empty_columns = torch::empty(
        {0, 512}, input.options().dtype(torch::kInt32));
    return {vectors, values, empty_indices, empty_flags, empty_columns};
  }

  auto candidate_data = at::index_select(
      input, 0, unsafe_indices).contiguous();
  auto candidate_vectors = at::index_select(
      vectors, 0, unsafe_indices).contiguous();
  auto candidate_values = at::index_select(
      values, 0, unsafe_indices).contiguous();
  auto scratch_vectors = factor_workspace.narrow(0, 0, candidate_count);
  CertificateState& state = refinement_state();
  ensure_certificate_state(state, candidate_data, candidate_count, 512);
  at::index_select_out(
      state.gram, initial_state.gram, 0, unsafe_indices);
  form_newton_correction512<<<candidate_count, 512>>>(
      state.gram.data_ptr<float>(), candidate_count);

  auto refined_vectors = torch::empty_like(candidate_vectors);
  torch::Tensor current_vectors = candidate_vectors;
  const int refinement_count =
      candidate_count < 320 ? 3 : (candidate_count < 512 ? 6 : 5);
  for (int refinement = 0; refinement < refinement_count; ++refinement) {
    torch::Tensor next_vectors =
        (refinement & 1) ? scratch_vectors : refined_vectors;
    at::bmm_out(next_vectors, current_vectors, state.gram);
    at::bmm_out(state.gram, next_vectors.transpose(1, 2), next_vectors);
    if (refinement + 1 < refinement_count) {
      form_newton_correction512<<<candidate_count, 512>>>(
          state.gram.data_ptr<float>(), candidate_count);
    } else {
      at::bmm_out(state.aq, candidate_data, next_vectors);
      certify_and_prepare_eigenpairs512<true, false><<<candidate_count, 512>>>(
          state.gram.data_ptr<float>(), state.aq.data_ptr<float>(),
          next_vectors.data_ptr<float>(), candidate_values.data_ptr<float>(),
          nullptr, state.flags.data_ptr<int>(), state.columns.data_ptr<int>(),
          candidate_count);
    }
    current_vectors = next_vectors;
  }

  vectors.index_copy_(0, unsafe_indices, current_vectors);
  values.index_copy_(0, unsafe_indices, candidate_values);
  auto remaining_positions = at::nonzero(
      state.flags.narrow(0, 0, candidate_count)).flatten();
  if (remaining_positions.numel() == 0) {
    auto empty_indices = torch::empty(
        {0}, input.options().dtype(torch::kInt64));
    auto empty_flags = torch::empty(
        {0}, input.options().dtype(torch::kInt32));
    auto empty_columns = torch::empty(
        {0, 512}, input.options().dtype(torch::kInt32));
    return {vectors, values, empty_indices, empty_flags, empty_columns};
  }
  auto remaining_indices = at::index_select(
      unsafe_indices, 0, remaining_positions);
  auto remaining_flags = at::index_select(
      state.flags.narrow(0, 0, candidate_count), 0, remaining_positions);
  auto remaining_columns = at::index_select(
      state.columns, 0, remaining_positions);

